-- "How to submit" tables from PaperCept (controls.papercept.net, "Submit a contribution" on each conference), stored in
-- venues.details.schedule. PaperCept dates are days: a row opens at 00:00 and closes at 23:59:59 Pacific Time on the
-- dates shown. First-stage rows carry `type` when the event has a matching submission type; the event page shows Submit
-- while a row is open and Closed otherwise.
update venues set details = jsonb_set(coalesce(details, '{}'::jsonb), '{schedule}', '{"time_zone": "America/Los_Angeles", "source": "PaperCept", "rows": [{"stage": "first", "label": "6-page full paper", "opens": "2026-03-02T00:00:00-08:00", "deadline": "2026-05-31T23:59:59-07:00", "type": "Regular paper"}, {"stage": "first", "label": "2-page industrial paper", "opens": "2026-03-02T00:00:00-08:00", "deadline": "2026-05-31T23:59:59-07:00"}, {"stage": "first", "label": "Invited session proposal", "opens": "2026-03-02T00:00:00-08:00", "deadline": "2026-05-31T23:59:59-07:00", "type": "Invited session proposal"}, {"stage": "first", "label": "Invited session paper", "opens": "2026-03-02T00:00:00-08:00", "deadline": "2026-05-31T23:59:59-07:00", "type": "Invited session paper"}, {"stage": "first", "label": "Plenary paper", "opens": "2026-03-02T00:00:00-08:00", "deadline": "2026-07-31T23:59:59-07:00"}, {"stage": "first", "label": "Keynote paper", "opens": "2026-03-02T00:00:00-08:00", "deadline": "2026-07-31T23:59:59-07:00"}, {"stage": "final", "label": "6-page full paper", "opens": "2026-07-10T00:00:00-07:00", "deadline": "2026-08-31T23:59:59-07:00"}, {"stage": "final", "label": "2-page industrial paper", "opens": "2026-07-10T00:00:00-07:00", "deadline": "2026-08-30T23:59:59-07:00"}, {"stage": "final", "label": "Invited session proposal", "opens": "2026-07-10T00:00:00-07:00", "deadline": "2026-08-30T23:59:59-07:00"}, {"stage": "final", "label": "Invited session paper", "opens": "2026-07-10T00:00:00-07:00", "deadline": "2026-08-30T23:59:59-07:00"}, {"stage": "final", "label": "6-page paper", "opens": "2026-07-10T00:00:00-07:00", "deadline": "2026-09-23T23:59:59-07:00"}]}'::jsonb) where slug = 'adconip-2026';
